  gameState.bombDefusing = false;
  gameState.defuseProgress = 0;
  gameState.hasDefuseKit = false;
  gameState.hasBomb = gameState.playerTeam === 't';

  // Respawn all bots
  bots.bots.forEach((bot, i) => {
