  const spawn = gameState.playerTeam === 'ct' 
    ? new THREE.Vector3(-30, 1, -30) 
    : new THREE.Vector3(30, 1, 30);
  body.position.copy(spawn);
  body.yaw = gameState.playerTeam === 'ct' ? 0 : Math.PI;
  body.velocity.set(0, 0, 0);
  body.health = 100;
